/* Pastel Dreams Theme - Auto-generated from tweakcn */

/* Light mode */
[data-theme="pastel-dreams-light"] {
  --background: #f8f3fa;
  --foreground: #364050;
  --card: #ffffff;
  --card-foreground: #364050;
  --popover: #ffffff;
  --popover-foreground: #364050;
  --primary: #a78bfb;
  --primary-foreground: #ffffff;
  --secondary: #e9d9fc;
  --secondary-foreground: #4b5666;
  --muted: #f4eaff;
  --muted-foreground: #6c727e;
  --accent: #f5e5f7;
  --accent-foreground: #364050;
  --destructive: #fba7a7;
  --destructive-foreground: #ffffff;
  --border: #e9d9fc;
  --input: #e9d9fc;
  --ring: #a78bfb;
  --chart-1: #a78bfb;
  --chart-2: #8c5df8;
  --chart-3: #7c38ee;
  --chart-4: #6d29d8;
  --chart-5: #5a20b5;
  --radius: 1.5rem;
  --sidebar: #e9d9fc;
  --sidebar-foreground: #364050;
  --sidebar-primary: #a78bfb;
  --sidebar-primary-foreground: #ffffff;
  --sidebar-accent: #f5e5f7;
  --sidebar-accent-foreground: #364050;
  --sidebar-border: #e9d9fc;
  --sidebar-ring: #a78bfb;
  --font-sans: Open Sans, sans-serif;
  --font-serif: Source Serif 4, serif;
  --font-mono: IBM Plex Mono, monospace;
  --shadow-color: #000000;
  --shadow-opacity: 0.08;
  --shadow-blur: 16px;
  --shadow-spread: -4px;
  --shadow-offset-x: 0px;
  --shadow-offset-y: 8px;
  --letter-spacing: 0em;
  --spacing: 0.25rem;
  --shadow-2xs: 0px 8px 16px -4px hsl(0 0% 0% / 0.04);
  --shadow-xs: 0px 8px 16px -4px hsl(0 0% 0% / 0.04);
  --shadow-sm:
    0px 8px 16px -4px hsl(0 0% 0% / 0.08), 0px 1px 2px -5px hsl(0 0% 0% / 0.08);
  --shadow:
    0px 8px 16px -4px hsl(0 0% 0% / 0.08), 0px 1px 2px -5px hsl(0 0% 0% / 0.08);
  --shadow-md:
    0px 8px 16px -4px hsl(0 0% 0% / 0.08), 0px 2px 4px -5px hsl(0 0% 0% / 0.08);
  --shadow-lg:
    0px 8px 16px -4px hsl(0 0% 0% / 0.08), 0px 4px 6px -5px hsl(0 0% 0% / 0.08);
  --shadow-xl:
    0px 8px 16px -4px hsl(0 0% 0% / 0.08), 0px 8px 10px -5px hsl(0 0% 0% / 0.08);
  --shadow-2xl: 0px 8px 16px -4px hsl(0 0% 0% / 0.2);
  --tracking-normal: 0em;
}

/* Dark mode */
