  --background: #1e1916;
  --foreground: #e1e7fd;
  --card: #2d2535;
  --card-foreground: #e1e7fd;
  --popover: #2d2535;
  --popover-foreground: #e1e7fd;
  --primary: #c1aaff;
  --primary-foreground: #1e1916;
  --secondary: #3e3248;
  --secondary-foreground: #d0d4db;
  --muted: #2d2535;
  --muted-foreground: #9ba2ae;
  --accent: #4b3e5b;
  --accent-foreground: #d0d4db;
  --destructive: #fba7a7;
  --destructive-foreground: #1e1916;
  --border: #3e3248;
  --input: #3e3248;
  --ring: #c1aaff;
  --chart-1: #c1aaff;
  --chart-2: #a78bfb;
  --chart-3: #8c5df8;
  --chart-4: #7c38ee;
  --chart-5: #6d29d8;
  --radius: 1.5rem;
  --sidebar: #3e3248;
  --sidebar-foreground: #e1e7fd;
  --sidebar-primary: #c1aaff;
  --sidebar-primary-foreground: #1e1916;
  --sidebar-accent: #4b3e5b;
  --sidebar-accent-foreground: #d0d4db;
  --sidebar-border: #3e3248;
  --sidebar-ring: #c1aaff;
  --font-sans: Open Sans, sans-serif;
